package cl.bancoxyz.batch;import java.util.*;import org.springframework.batch.core.*;import org.springframework.batch.core.launch.JobLauncher;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/batch") public class BatchController{private final JobLauncher launcher;private final Map<String,Job> jobs;public BatchController(JobLauncher l,@Qualifier("dailyTransactionsJob")Job a,@Qualifier("monthlyInterestJob")Job b,@Qualifier("annualStatementsJob")Job c){launcher=l;jobs=Map.of("transactions",a,"interests",b,"statements",c);}@PostMapping("/{name}") public ResponseEntity<?> run(@PathVariable String name)throws Exception{Job j=jobs.get(name);if(j==null)return ResponseEntity.badRequest().body(Map.of("error","Use transactions, interests o statements"));JobExecution e=launcher.run(j,new JobParametersBuilder().addLong("run.id",System.currentTimeMillis()).toJobParameters());return ResponseEntity.accepted().body(Map.of("job",j.getName(),"status",e.getStatus().toString(),"executionId",e.getId()));}}